('01a18240-db1f-7c0f-b1b3-556848c6300f', 'en', 'welcome.featuresLink', 'Features'),
('01a18240-db20-7334-b456-99a855d1efb9', 'en', 'welcome.badge', 'Open source · MIT licensed'),
('01a18240-db21-74be-92ec-d264d7d4f310', 'en', 'welcome.title', 'The multi-tenant SaaS core'),
('01a18240-db22-77db-8e29-4a6287bca252', 'en', 'welcome.highlight', 'you would build anyway.'),
('01a18240-db23-7e00-9f1f-79adbb7d9cdf', 'en', 'welcome.text', 'Tenancy, auth, roles, API keys, encrypted tenant secrets, rate limiting, jobs and notifications — already built, tested and documented. Start on your product on day one.'),
('01a18240-db24-7e2a-8fd7-a5b147420270', 'en', 'welcome.openDashboard', 'Open the dashboard'),
('01a18240-db25-7c06-afe8-63e56537cd3e', 'en', 'welcome.viewGithub', 'View on GitHub'),
('01a18240-db26-7f87-a74f-e8dcc70c3024', 'en', 'welcome.featuresTitle', 'Everything a SaaS needs before its first feature'),
('01a18240-db27-7dbe-9df5-56684b740a81', 'en', 'welcome.featuresText', 'Each piece follows one rule set, written down in CLAUDE.md and enforced by tests.'),
('01a18240-db28-7e98-b326-ab9176687fc5', 'en', 'welcome.stackTitle', 'Built on tools you already know'),
('01a18240-db29-77a5-8964-6a5482ee1932', 'en', 'welcome.ctaTitle', 'Start on your product, not on plumbing.'),
('01a18240-db2a-7477-9ab0-aaae72133082', 'en', 'welcome.ctaText', 'Clone the repository, run one command, and sign in to a working dashboard.'),
('01a18240-db2b-71a3-8b80-c9850b5e2ab2', 'en', 'welcome.getCode', 'Get the code'),
('01a18240-db2c-7b22-a7f1-609a157fc328', 'en', 'welcome.footer', 'MIT licensed. Built with NestJS and Next.js.'),
('01a18240-db2d-7220-b5fe-82dc858e38c1', 'en', 'feature.multiTenant.title', 'Multi-tenant by default'),
('01a18240-db2e-7080-bfce-deacf75df36a', 'en', 'feature.multiTenant.text', 'Every table carries a tenant ID, every query filters by it, and a test proves tenant A never reads tenant B.'),
('01a18240-db2f-7485-b04c-0ee7af5835b0', 'en', 'feature.auth.title', 'Pluggable auth'),
('01a18240-db30-7fb0-8a77-f1f339b7424e', 'en', 'feature.auth.text', 'Built-in JWT with Argon2id, or Clerk. One setting switches them.'),
('01a18240-db31-7a4a-b2cc-4daef435b771', 'en', 'feature.rbac.title', 'Role-based access'),
('01a18240-db32-70dc-a0f3-c7d4814c6200', 'en', 'feature.rbac.text', 'Four roles, guards on every route, denied by default.'),
('01a18240-db33-7234-9e4a-c93892c11517', 'en', 'feature.byok.title', 'Bring your own keys'),
('01a18240-db34-70a5-87ec-ac7641851499', 'en', 'feature.byok.text', 'Tenant secrets sealed with AES-256-GCM, never returned by the API.'),
('01a18240-db35-7b3c-8753-15d197e70507', 'en', 'feature.rateLimit.title', 'Rate limiting'),
('01a18240-db36-7581-b5a6-fe5d233d75cd', 'en', 'feature.rateLimit.text', 'Redis sliding windows per tenant, user and tier, with Retry-After.'),
('01a18240-db37-7a51-8d2b-d5c33bf5e758', 'en', 'feature.jobs.title', 'Background jobs'),
('01a18240-db38-7a39-a333-67be10671f68', 'en', 'feature.jobs.text', 'BullMQ workers with retries, backoff and dead-letter queues.'),
('01a18240-db39-73b2-ab45-9ddbef663ca6', 'en', 'feature.modules.title', 'Plug-and-play modules'),
('01a18240-db3a-77e9-9ff1-df8b4c5ef734', 'en', 'feature.modules.text', 'Email, push and file storage are folders. Delete one and the app still compiles; the dashboard hides its settings.'),
('01a18240-db3b-716f-8088-9bd0d4ef7d08', 'en', 'feature.notifications.title', 'Notifications'),
('01a18240-db3c-7ef9-bbaa-6a6336b75532', 'en', 'feature.notifications.text', 'Real-time SSE, push through FCM and email through Resend.'),
('01a18240-db3d-76fc-8618-11dac41b429a', 'en', 'feature.audit.title', 'Audit trail'),
('01a18240-db3e-7cb1-a11c-05fc1964023a', 'en', 'feature.audit.text', 'Every write logged, with ISO 27001, 27701 and 42001 in mind.'),
('01a18240-db3f-7f4c-962a-cbbaf04cca22', 'en', 'feature.uploads.title', 'Direct uploads'),
('01a18240-db40-70d4-86f5-97338307b119', 'en', 'feature.uploads.text', 'Presigned URLs to R2 or S3: file bytes never touch the API.');
